@pytest.mark.parametrize(
    "session",
    [
        pytest.param({"hls-audio-select": ["Deutsch", "Français", "Español"]}, id="multiple names"),
    ],
    indirect=["session"],
)
@pytest.mark.parametrize(
    "_playlist",
    [
        pytest.param({"playlist": "hls/test_media_language_names.m3u8"}),
    ],
    indirect=["_playlist"],
)
def test_multiple_names(self, session: Streamlink, stream: MuxedHLSStream):
    assert isinstance(stream, MuxedHLSStream)
    assert [substream.url for substream in stream.substreams] == [
        "http://mocked/path/playlist.m3u8",
        "http://mocked/path/de.m3u8",
        "http://mocked/path/fr.m3u8",
        "http://mocked/path/es.m3u8",
    ]
